function assign5(m,side){let s=m.sides[side],plan=m.plans[side],enemy=m.sides[1-side];if(m.clock<s.planUntil)return;s.planUntil=m.clock+30;let target=targetLane4(m,side);s.targetLane=target;let threat=enemy.targetLane??target;for(let p of alive4(m,side)){if(p.combatUntil>m.clock)continue;let zone;if(m.clock<540)zone=[side?0:2,1,side?2:0,side?2:0,side?0:2][p.role];else if(plan==='rosh')zone=p.role===0&&m.clock<1000?3:4;else if(['siege','throne'].includes(plan))zone=p.role===0&&m.clock<1500?3:target;else if(plan==='defend')zone=p.role===0&&towerCount4(s)<3?3:threat;else if(plan==='split')zone=p.role===0?3:p.role===2?(target+1)%3:target;else zone=p.role===0?3:p.role===1?1:p.role===2?target:p.role===3?target:(target+1)%3;move5(m,p,zone,plan==='defend');}}
