function choosePlan4(m,side){let s=m.sides[side],enemy=m.sides[1-side],order=m.orders[side];if(order.until>m.clock&&order.type!=='coach')return order.type;let count=alive4(m,side).length,enemyCount=alive4(m,1-side).length,ratio=fightingPower4(m,side)/Math.max(1,fightingPower4(m,1-side)),outer=enemy.lanes.some(l=>l.towers[1].hp>0);if(count<3)return 'defend';if(enemy.lanes.some(l=>l.towers[2].hp<=0)&&count>=3&&ratio>.95)return 'siege';if(m.clock<480)return 'farm';if(enemyCount<3)return enemy.lanes.some(l=>l.towers[2].hp<=0)?'throne':'siege';if(ratio<.8)return 'defend';if(m.roshan.alive&&m.clock>1100&&ratio>1.08&&count>=4&&s.aegisUntil<=m.clock)return 'rosh';if(s.aegisUntil>m.clock||ratio>1.4)return 'siege';if(m.clock%240>120&&enemyCount>=4&&outer)return 'farm';if(outer&&(ratio>1.03||avg(s.heroes.map(p=>heroMeta4(p.hero).push))>3.4))return 'siege';if(!outer&&ratio>1.1)return m.clock%240<90?'siege':'farm';return m.clock%300<100?'vision':'farm'}
