function economy4(m,side,dt){let s=m.sides[side];for(let p of s.heroes){income5(m,side,p,100*dt/60,'passive');if(p.deadUntil>m.clock)continue;p.health=clamp(p.health+dt*(p.zone===5?3:.2),0,100);if(p.travelUntil>m.clock||p.combatUntil>m.clock)continue;let h=heroMeta4(p.hero),amount=0;if(p.zone<3){let pool=m.laneFarm[side][p.zone],peers=locals5(m,side,p.zone),priority=peers.reduce((n,q)=>n+(q.role<3?8:1),0),cap=(p.role<3?570:170)*(1+(h.farm-3)*.07)*dt/60;amount=Math.min(pool*(p.role<3?8:1)/Math.max(1,priority),cap);m.laneFarm[side][p.zone]-=amount;}else if(p.zone===3){let cap=(480+h.farm*85)*dt/60;amount=Math.min(m.camps[side],cap);m.camps[side]-=amount;}income5(m,side,p,amount,'farm');p.farmGold+=amount;p.lastHits+=amount/43;p.xp+=amount*(p.role<3?1.2:1.6)+dt*2;p.level=Math.min(30,1+Math.floor(Math.sqrt(p.xp/38)));let reserve=m.clock>=1800?buybackCost4(p):0;if(p.bank>=p.nextItem+reserve){let index=p.items.length,name=index===0?'Power Treads':index===1?(p.role===0?'Предмет фарма':p.role===1?'Предмет урона':'Blink / аура'):index===2?(p.role<3?'Black King Bar':'Force Staff'):index===3?(p.role===0?'Предмет урона':'Контроль / сейв'):'Поздний предмет';p.bank-=p.nextItem;p.items.push({at:m.clock,cost:p.nextItem,name});event4(m,p.name+': '+name+' · '+cash(p.nextItem),'item',{side});p.nextItem=Math.min(6000,Math.round(p.nextItem*1.4));}}}
function resources5(m,dt){let minute=Math.floor(m.clock/60);if(minute!==m.resourceMinute){m.resourceMinute=minute;for(let side of [0,1]){let s=m.sides[side],access=clamp(.62+s.control*.75,.7,1.3);m.camps[side]=Math.min(m.camps[side]+(minute<8?500:1200)*access,2100);}}if(m.clock>=m.waveNext){m.waveNext=m.clock+30;for(let lane=0;lane<3;lane++){for(let side of [0,1]){let strength=locals5(m,side,lane).reduce((n,p)=>n+(p.role<3?1:.3)*(1+heroMeta4(p.hero).lane*.08),0),opp=locals5(m,1-side,lane).reduce((n,p)=>n+(p.role<3?1:.3)*(1+heroMeta4(p.hero).lane*.08),0);let contest=clamp(.82+(strength-opp)*.1,.45,1);m.laneFarm[side][lane]=Math.min(700,m.laneFarm[side][lane]+(185+minute*2.5)*contest);m.waveBodies[lane].push({side,pos:side===0?-100:100,hp:1+(m.sides[1-side].lanes[lane].rax.hp<=0?1.5:0),siege:minute>0&&minute%5===0});}}}
for(let lane=0;lane<3;lane++){let forces=[0,1].map(side=>locals5(m,side,lane).reduce((n,p)=>n+(p.role<3?1:.4)*(heroMeta4(p.hero).wave*.1+.5)*(1+p.nw/20000),0));let pressure=(forces[0]-forces[1])*.6+(m.sides[0].control-m.sides[1].control)*.5+(m.sides[1].lanes[lane].rax.hp<=0?.8:0)-(m.sides[0].lanes[lane].rax.hp<=0?.8:0);m.waves[lane]=clamp(m.waves[lane]+pressure*dt,-90,90);for(let wave of m.waveBodies[lane]){let sign=wave.side===0?1:-1;wave.pos+=sign*dt*2.2;if(sign*(wave.pos-m.waves[lane])>0){wave.hp-=dt*.09*(1+forces[1-wave.side]);wave.pos=m.waves[lane];}}m.waveBodies[lane]=m.waveBodies[lane].filter(w=>w.hp>0&&Math.abs(w.pos)<110);}}
function participants5(m,side,zone){return locals5(m,side,zone).filter(p=>p.health>10)}
