function battle5(m,dt){let b=m.battle;if(!b)return;let ps=[0,1].map(side=>participants5(m,side,b.zone).filter(p=>b.groups[side].includes(p.role)));let power=ps.map((g,side)=>g.reduce((n,p)=>n+unitPower5(m,p),0)*(b.highground&&side!==b.attacker?1.28:1)*(1+m.smokeBonus[side]*.2));let impacts=ps.map((g,side)=>{if(!g.length||!ps[1-side].length)return null;let control=avg(g.map(p=>heroMeta4(p.hero).control)),victim=weighted4(ps[1-side],ps[1-side].map(p=>(p.role>=3?1.5:1)*(1.5-p.health/100))),ratio=power[side]/Math.max(1,power[1-side]),damage=dt*(8+control*.8)*Math.sqrt(g.length/2)*clamp(ratio,.3,2.7)*(.8+rng()*.4);return {victim,damage}});for(let side of [0,1]){let hit=impacts[side];if(!hit)continue;hit.victim.health-=hit.damage;if(hit.victim.health<=0){kill5(m,side,hit.victim,ps[side].filter(p=>p.deadUntil<=m.clock));b.kills[side]++;}}for(let side of [0,1])for(let p of ps[side])if(p.ultUntil<=m.clock&&heroMeta4(p.hero).control>=4)p.ultUntil=m.clock+heroMeta4(p.hero).ult;
if(m.clock>=b.ends||ps.some(g=>!g.length)){for(let side of [0,1])for(let p of ps[side]){p.combatUntil=m.clock;if(p.health<35){move5(m,p,5);m.sides[side].planUntil=m.clock+30;}}event4(m,'Размен '+b.kills.join(':')+'. Выжившим нужно восстановиться и дойти до объекта.','fight-end');m.battle=null;m.lastFight=m.clock;m.nextFight=m.clock+int(50,120);m.smokeBonus=[0,0];}}
function objectives4(m,side,dt){let s=m.sides[side],enemy=m.sides[1-side],plan=m.plans[side];if(m.clock<s.nextObjective)return;if(plan==='rosh'&&m.roshan.alive){let ps=locals5(m,side,4);if(ps.length<3||m.battle?.zone===4)return;if(locals5(m,1-side,4).length>=2){fight4(m,side,false,4);return}m.roshan.progress[side]+=dt*ps.reduce((n,p)=>n+unitPower5(m,p),0)/1400;if(m.roshan.progress[side]>60){m.roshan.alive=false;m.roshan.spawnAt=m.clock+int(480,660);m.roshan.progress=[0,0];s.aegisUntil=m.clock+300;s.aegisHero=ps.sort((a,b)=>a.role-b.role)[0].role;s.roshKills++;for(let p of s.heroes)income5(m,side,p,135,'objects');s.planUntil=0;event4(m,S.teams[s.team].short+' забирает Рошана; Аегис у '+s.heroes[s.aegisHero].name+'.','roshan',{side});}return}
if(!['siege','throne','split'].includes(plan)||m.clock<300)return;let t=availableTarget4(m,side),ps=locals5(m,side,t.lane).filter(p=>p.health>35),defenders=locals5(m,1-side,t.lane),sign=side===0?1:-1,front=sign*m.waves[t.lane],required=[0,5,32,62,75,80][t.tier];if(!ps.length||m.battle?.zone===t.lane)return;let wave=m.waveBodies[t.lane].some(w=>w.side===side&&sign*w.pos>=required-8);if(front<required||!wave){if(t.tier>=2)t.entity.hp=Math.min(t.entity.max,t.entity.hp+dt*25);return;}if(enemy.glyphUntil>m.clock)return;let attack=ps.reduce((n,p)=>n+unitPower5(m,p),0),defense=defenders.reduce((n,p)=>n+unitPower5(m,p),0);if(defenders.length&&m.clock-m.lastFight>40){fight4(m,side,t.tier>=3,t.lane);return}if(t.tier>=3&&defense>attack*1.4)return;let damage=ps.reduce((n,p)=>n+(5+heroMeta4(p.hero).push*3+p.nw*.0007)*(p.role<3?1:.5),0)*dt*(defenders.length?.25:1);if(m.waveBodies[t.lane].some(w=>w.side===side&&w.siege))damage*=1.3;if(enemy.glyphReady<=m.clock&&t.entity.hp<t.entity.max*.55&&(side!==0||m.orders[0].type==='coach')){enemy.glyphUntil=m.clock+7;enemy.glyphReady=m.clock+300;event4(m,S.teams[enemy.team].short+' включает Glyph.','glyph');return}t.entity.hp=Math.max(0,t.entity.hp-damage);if(t.entity.hp===0){m.objectiveLog.push({sec:m.clock,side,lane:t.lane,tier:t.tier,type:t.type});event4(m,S.teams[s.team].short+' разрушает '+t.label+'. Перегруппировка.','objective',{side});s.nextObjective=m.clock+(t.tier<3?35:15);m.waves[t.lane]-=sign*8;if(t.type==='ancient'){m.finishedSide=side;return}for(let p of s.heroes)income5(m,side,p,t.type==='tower'?100+t.tier*20:90,'objects');if(t.type==='tower'&&!enemy.fortifiedTiers.includes(t.tier)){enemy.fortifiedTiers.push(t.tier);enemy.glyphReady=m.clock;}s.planUntil=0;}}
function simulateTick4(m,dt=10){if(m.finishedSide!=null)return;init5(m);m.clock+=dt;for(let side of [0,1]){let s=m.sides[side];for(let p of s.heroes){if(p.deadUntil>m.clock)continue;if(p.respawnTravel){p.respawnTravel=false;p.zone=5;p.destination=5;s.planUntil=0;}if(p.travelUntil&&p.travelUntil<=m.clock){p.zone=p.destination;p.travelUntil=0;}if(p.zone===5&&p.health>=80&&p.combatUntil<=m.clock)s.planUntil=0;}if(s.nextSmoke<=m.clock){s.smokes=Math.min(3,s.smokes+1);s.nextSmoke=m.clock+480}if(s.aegisUntil&&s.aegisUntil<=m.clock){s.aegisUntil=0;event4(m,'Аегис истёк.','aegis')}m.plans[side]=choosePlan4(m,side);assign5(m,side);autoBuyback5(m,side);let ownTowers=towerCount4(s),enemyTowers=towerCount4(m.sides[1-side]),desired=clamp(.5+(enemyTowers-ownTowers)*.045+(alive4(m,side).length-alive4(m,1-side).length)*.025,.2,.8);s.control+=(desired-s.control)*.03;s.vision=clamp(s.vision+(m.plans[side]==='vision'?.005:-.001),.2,.85);}
if(!m.roshan.alive&&m.roshan.spawnAt<=m.clock){m.roshan.alive=true;event4(m,'Рошан появился.','roshan')}resources5(m,dt);for(let side of [0,1])economy4(m,side,dt);if(m.battle)battle5(m,dt);else if(m.clock>=m.nextFight)fight4(m);for(let side of (rng()<.5?[0,1]:[1,0])){objectives4(m,side,dt);if(m.finishedSide!=null)break;}sync4(m);if(m.clock%60===0)snapshot4(m);}
const buyBase5=buyback4;buyback4=function(i){let m=S.active?.live,p=m?.sides[0].heroes[i];let was=p?.deadUntil>m?.clock;buyBase5(i);if(was&&p.deadUntil<=m.clock){p.zone=5;p.destination=5;p.travelUntil=0;p.respawnTravel=false;m.sides[0].planUntil=0;render();}};
heroTable4=function(m,side){let html=heroTableBase5(m,side);if(!m.sides||m.revision!==5)return html;return html.replace('</section>',`<div class="position-list">${m.sides[side].heroes.map(p=>`<span><b>${esc(p.name)}</b> ${p.deadUntil>m.clock?'мёртв':p.travelUntil>m.clock?'переход '+Math.ceil(p.travelUntil-m.clock)+' с.':['верх','мид','низ','лес','Рошан','база'][p.zone]} · LH ${Math.floor(p.lastHits||0)}</span>`).join('')}</div></section>`)};
objectivesView4=function(m){let html=objectivesBase5(m);if(m.revision!==5)return html;return `<section class="panel"><h2>Карта и ресурсы</h2><p class="sub">Герои участвуют только в локальных боях. Переходы и телепорты занимают время. Волны нужны для снятия защиты строений.</p>${[0,1,2].map((l)=>`<div class="macro-lane"><b>${['Верх','Мид','Низ'][l]}</b><div class="macro-track"><i style="left:${(m.waves[l]+100)/2}%"></i></div><small>${locals5(m,0,l).map(p=>esc(p.name)).join(', ')||'—'} / ${locals5(m,1,l).map(p=>esc(p.name)).join(', ')||'—'}</small></div>`).join('')}<div class="stats">${m.sides.map((s,i)=>stat(S.teams[s.team].short+' · доход',cash(m.accounting[i].farm+m.accounting[i].passive), 'Фарм + пассивный; убийства '+cash(m.accounting[i].kills)+'; объекты '+cash(m.accounting[i].objects))).join('')}</div></section>`+html};
